SELECT o.status, CASE WHEN YEAR(o.order_date) < 2024 THEN 'before_2024' WHEN YEAR(o.order_date) = 2024 THEN '2024' ELSE 'after_2024' END AS order_cohort, MIN(s.shipped_date) AS min_shipped_date FROM shipments s INNER JOIN orders o ON s.order_id = o.id GROUP BY o.status, CASE WHEN YEAR(o.order_date) < 2024 THEN 'before_2024' WHEN YEAR(o.order_date) = 2024 THEN '2024' ELSE 'after_2024' END ORDER BY status ASC;
